// Native dialogs on modern browsers; accessible fallback for embedded webviews.
const stack=[],wired=new WeakSet(),expectedClose=new WeakMap();
let bodyStyle='',scrollY=0;
const focusables=el=>[...el.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')].filter(x=>x.getClientRects().length);
function lock(){if(stack.length)return;scrollY=window.scrollY;bodyStyle=document.body.style.cssText;Object.assign(document.body.style,{position:'fixed',top:-scrollY+'px',left:'0',right:'0',width:'100%',overflow:'hidden'});document.body.classList.add('dialog-open');}
export function openDialog(el){if(stack.some(x=>x.el===el))return;if(!wired.has(el)){wired.add(el);el.addEventListener('close',()=>{const expected=expectedClose.get(el)||0;if(expected){expectedClose.set(el,expected-1);return;}if(stack.some(x=>x.el===el))closeDialog(el);});}lock();const previous=stack[stack.length-1];if(previous)previous.el.setAttribute('aria-hidden','true');const item={el,focus:document.activeElement,overlay:null,native:false};stack.push(item);el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.removeAttribute('aria-hidden');if(!el.hasAttribute('aria-label')&&!el.hasAttribute('aria-labelledby'))el.setAttribute('aria-label','人生纪事');
 try{if(typeof el.showModal!=='function')throw Error('fallback');el.showModal();item.native=true;}catch{const overlay=document.createElement('div');overlay.className='dialog-backdrop';overlay.style.zIndex=String(1100+stack.length*2);overlay.setAttribute('aria-hidden','true');document.body.append(overlay);item.overlay=overlay;el.classList.add('dialog-fallback');el.style.zIndex=String(1101+stack.length*2);el.setAttribute('open','');}
 el.scrollTop=0;const first=focusables(el)[0];if(first)try{first.focus({preventScroll:true});}catch{first.focus();}
}
export function closeDialog(el){const index=stack.findIndex(x=>x.el===el);if(index<0){if(el.open&&typeof el.close==='function')el.close();return;}const [item]=stack.splice(index,1);if(item.native&&el.open){expectedClose.set(el,(expectedClose.get(el)||0)+1);el.close();}else el.removeAttribute('open');item.overlay?.remove();el.classList.remove('dialog-fallback');el.style.removeProperty('z-index');el.removeAttribute('aria-modal');const top=stack[stack.length-1];if(top)top.el.removeAttribute('aria-hidden');else{document.body.classList.remove('dialog-open');document.body.style.cssText=bodyStyle;window.scrollTo(0,scrollY);}if(!top||index===stack.length)try{item.focus?.focus({preventScroll:true});}catch{item.focus?.focus();}
}
document.addEventListener('keydown',e=>{const top=stack[stack.length-1];if(!top||top.native)return;if(e.key==='Escape'){e.preventDefault();const cancel=new Event('cancel',{cancelable:true});if(top.el.dispatchEvent(cancel))closeDialog(top.el);}else if(e.key==='Tab'){const list=focusables(top.el);if(!list.length){e.preventDefault();return;}const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
export function mobileJump(id){const el=document.getElementById(id);if(!el)return;el.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
export function focusCurrent(){if(window.matchMedia?.('(max-width: 760px)').matches)mobileJump('life-main');}
